import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        final int MOD = (int) 1e9 + 7;
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int k = sc.nextInt();
        int p;
        if (k < 2) {
            p = n - (1 - k);
        } else {
            int cycle = 1;
            int val = k;
            while (val != 1) {
                val = (int)((long)val * k % n);
                cycle++;
            }
            p = (n - 1) / cycle;
        }
        System.out.println(pow(n, p, MOD));
    }

    private static long pow(long base, int exp, int mod) {
        long result = 1;
        long cur = base % mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * cur) % mod;
            }
            cur = (cur * cur) % mod;
            exp >>= 1;
        }
        return result;
    }
}
